8: 
9: /*
10:  * Module dependencies.
11:  */
12: const fs = require('fs');
13: const os = require('os');
14: const path = require('path');
15: const crypto = require('crypto');
16: const _c = { fs: fs.constants, os: os.constants };
17: 
18: /*
19:  * The working inner variables.
20:  */
21: const // the random characters to choose from
22:   RANDOM_CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz',
23:   TEMPLATE_PATTERN = /XXXXXX/,
24:   DEFAULT_TRIES = 3,
25:   CREATE_FLAGS = (_c.O_CREAT || _c.fs.O_CREAT) | (_c.O_EXCL || _c.fs.O_EXCL) | (_c.O_RDWR || _c.fs.O_RDWR),
26:   // constants are off on the windows platform and will not match the actual errno codes
27:   IS_WIN32 = os.platform() === 'win32',
28:   EBADF = _c.EBADF || _c.os.errno.EBADF,
29:   ENOENT = _c.ENOENT || _c.os.errno.ENOENT,
30:   DIR_MODE = 0o700 /* 448 */,
31:   FILE_MODE = 0o600 /* 384 */,
32:   EXIT = 'exit',
33:   // this will hold the objects need to be removed on exit
34:   _removeObjects = [],
35:   // API change in fs.rmdirSync leads to error when passing in a second parameter, e.g. the callback
36:   FN_RMDIR_SYNC = fs.rmdirSync.bind(fs);
37: 
38: let _gracefulCleanup = false;
39: 
40: /**
41:  * Recursively remove a directory and its contents.
42:  *
43:  * @param {string} dirPath path of directory to remove
44:  * @param {Function} callback
45:  * @private
46:  */
47: function rimraf(dirPath, callback) {
48:   return fs.rm(dirPath, { recursive: true }, callback);
49: }
50: 
51: /**
52:  * Recursively remove a directory and its contents, synchronously.
53:  *
54:  * @param {string} dirPath path of directory to remove
55:  * @private
56:  */
57: function FN_RIMRAF_SYNC(dirPath) {
58:   return fs.rmSync(dirPath, { recursive: true });
59: }
60: 
61: /**
62:  * Gets a temporary file name.
63:  *
64:  * @param {(Options|tmpNameCallback)} options options or callback
65:  * @param {?tmpNameCallback} callback the callback function
66:  */
67: function tmpName(options, callback) {
68:   const args = _parseArguments(options, callback),
69:     opts = args[0],
70:     cb = args[1];
71: 
72:   _assertAndSanitizeOptions(opts, function (err, sanitizedOptions) {
73:     if (err) return cb(err);
74: 
75:     let tries = sanitizedOptions.tries;
76:     (function _getUniqueName() {
77:       try {
78:         const name = _generateTmpName(sanitizedOptions);
79: 
80:         // check whether the path exists then retry if needed
81:         fs.stat(name, function (err) {
82:           /* istanbul ignore else */
83:           if (!err) {
84:             /* istanbul ignore else */
85:             if (tries-- > 0) return _getUniqueName();
86: 
87:             return cb(new Error('Could not get a unique tmp filename, max tries reached ' + name));
88:           }
89: 
90:           cb(null, name);
91:         });
92:       } catch (err) {
93:         cb(err);
94:       }
95:     })();
96:   });
97: }
98: 
99: /**
100:  * Synchronous version of tmpName.
101:  *
102:  * @param {Object} options
103:  * @returns {string} the generated random name
104:  * @throws {Error} if the options are invalid or could not generate a filename
105:  */
106: function tmpNameSync(options) {
107:   const args = _parseArguments(options),
108:     opts = args[0];
109: 
110:   const sanitizedOptions = _assertAndSanitizeOptionsSync(opts);
111: 
112:   let tries = sanitizedOptions.tries;
113:   do {
114:     const name = _generateTmpName(sanitizedOptions);
115:     try {
116:       fs.statSync(name);
117:     } catch (e) {
118:       return name;
119:     }
120:   } while (tries-- > 0);
121: 
122:   throw new Error('Could not get a unique tmp filename, max tries reached');
123: }
124: 
125: /**
126:  * Creates and opens a temporary file.
127:  *
128:  * @param {(Options|null|undefined|fileCallback)} options the config options or the callback function or null or undefined
129:  * @param {?fileCallback} callback
130:  */
131: function file(options, callback) {
132:   const args = _parseArguments(options, callback),
133:     opts = args[0],
134:     cb = args[1];
135: 
136:   // gets a temporary filename
137:   tmpName(opts, function _tmpNameCreated(err, name) {
138:     /* istanbul ignore else */
139:     if (err) return cb(err);
140: 
141:     // create and open the file
142:     fs.open(name, CREATE_FLAGS, opts.mode || FILE_MODE, function _fileCreated(err, fd) {
143:       /* istanbu ignore else */
144:       if (err) return cb(err);
145: 
146:       if (opts.discardDescriptor) {
147:         return fs.close(fd, function _discardCallback(possibleErr) {
148:           // the chance of getting an error on close here is rather low and might occur in the most edgiest cases only
149:           return cb(possibleErr, name, undefined, _prepareTmpFileRemoveCallback(name, -1, opts, false));
150:         });
151:       } else {
152:         // detachDescriptor passes the descriptor whereas discardDescriptor closes it, either way, we no longer care
153:         // about the descriptor
154:         const discardOrDetachDescriptor = opts.discardDescriptor || opts.detachDescriptor;
155:         cb(null, name, fd, _prepareTmpFileRemoveCallback(name, discardOrDetachDescriptor ? -1 : fd, opts, false));
156:       }
157:     });
158:   });
159: }
160: 
161: /**
162:  * Synchronous version of file.
163:  *
164:  * @param {Options} options
165:  * @returns {FileSyncObject} object consists of name, fd and removeCallback
166:  * @throws {Error} if cannot create a file
167:  */
168: function fileSync(options) {
169:   const args = _parseArguments(options),
170:     opts = args[0];
171: 
172:   const discardOrDetachDescriptor = opts.discardDescriptor || opts.detachDescriptor;
173:   const name = tmpNameSync(opts);
174:   let fd = fs.openSync(name, CREATE_FLAGS, opts.mode || FILE_MODE);
175:   /* istanbul ignore else */
176:   if (opts.discardDescriptor) {
177:     fs.closeSync(fd);
178:     fd = undefined;
179:   }
180: 
181:   return {
182:     name: name,
183:     fd: fd,
184:     removeCallback: _prepareTmpFileRemoveCallback(name, discardOrDetachDescriptor ? -1 : fd, opts, true)
185:   };
186: }
187: 
188: /**
189:  * Creates a temporary directory.
190:  *
191:  * @param {(Options|dirCallback)} options the options or the callback function
192:  * @param {?dirCallback} callback
193:  */
194: function dir(options, callback) {
195:   const args = _parseArguments(options, callback),
196:     opts = args[0],
197:     cb = args[1];
198: 
199:   // gets a temporary filename
200:   tmpName(opts, function _tmpNameCreated(err, name) {
201:     /* istanbul ignore else */
202:     if (err) return cb(err);
203: 
204:     // create the directory
205:     fs.mkdir(name, opts.mode || DIR_MODE, function _dirCreated(err) {
206:       /* istanbul ignore else */
207:       if (err) return cb(err);
208: 
209:       cb(null, name, _prepareTmpDirRemoveCallback(name, opts, false));
210:     });
211:   });
212: }
213: 
214: /**
215:  * Synchronous version of dir.
216:  *
217:  * @param {Options} options
218:  * @returns {DirSyncObject} object consists of name and removeCallback
219:  * @throws {Error} if it cannot create a directory
220:  */
221: function dirSync(options) {
222:   const args = _parseArguments(options),
223:     opts = args[0];
224: 
225:   const name = tmpNameSync(opts);
226:   fs.mkdirSync(name, opts.mode || DIR_MODE);
227: 
228:   return {
229:     name: name,
230:     removeCallback: _prepareTmpDirRemoveCallback(name, opts, true)
231:   };
232: }
233: 
234: /**
235:  * Removes files asynchronously.
236:  *
237:  * @param {Object} fdPath
238:  * @param {Function} next
239:  * @private
240:  */
241: function _removeFileAsync(fdPath, next) {
242:   const _handler = function (err) {
243:     if (err && !_isENOENT(err)) {
244:       // reraise any unanticipated error
245:       return next(err);
246:     }
247:     next();
248:   };
249: 
250:   if (0 <= fdPath[0])
251:     fs.close(fdPath[0], function () {
252:       fs.unlink(fdPath[1], _handler);
253:     });
254:   else fs.unlink(fdPath[1], _handler);
255: }
256: 
257: /**
258:  * Removes files synchronously.
259:  *
260:  * @param {Object} fdPath
261:  * @private
262:  */
263: function _removeFileSync(fdPath) {
264:   let rethrownException = null;
265:   try {
266:     if (0 <= fdPath[0]) fs.closeSync(fdPath[0]);
267:   } catch (e) {
268:     // reraise any unanticipated error
269:     if (!_isEBADF(e) && !_isENOENT(e)) throw e;
270:   } finally {
271:     try {
272:       fs.unlinkSync(fdPath[1]);
273:     } catch (e) {
274:       // reraise any unanticipated error
275:       if (!_isENOENT(e)) rethrownException = e;
276:     }
277:   }
278:   if (rethrownException !== null) {
279:     throw rethrownException;
280:   }
281: }
282: 
283: /**
284:  * Prepares the callback for removal of the temporary file.
285:  *
286:  * Returns either a sync callback or a async callback depending on whether
287:  * fileSync or file was called, which is expressed by the sync parameter.
288:  *
289:  * @param {string} name the path of the file
290:  * @param {number} fd file descriptor
291:  * @param {Object} opts
292:  * @param {boolean} sync
293:  * @returns {fileCallback | fileCallbackSync}
294:  * @private
295:  */
296: function _prepareTmpFileRemoveCallback(name, fd, opts, sync) {
297:   const removeCallbackSync = _prepareRemoveCallback(_removeFileSync, [fd, name], sync);
298:   const removeCallback = _prepareRemoveCallback(_removeFileAsync, [fd, name], sync, removeCallbackSync);
299: 
300:   if (!opts.keep) _removeObjects.unshift(removeCallbackSync);
301: 
302:   return sync ? removeCallbackSync : removeCallback;
303: }
304: 
305: /**
306:  * Prepares the callback for removal of the temporary directory.
307:  *
308:  * Returns either a sync callback or a async callback depending on whether
309:  * tmpFileSync or tmpFile was called, which is expressed by the sync parameter.
310:  *
311:  * @param {string} name
312:  * @param {Object} opts
313:  * @param {boolean} sync
314:  * @returns {Function} the callback
315:  * @private
316:  */
317: function _prepareTmpDirRemoveCallback(name, opts, sync) {
318:   const removeFunction = opts.unsafeCleanup ? rimraf : fs.rmdir.bind(fs);
319:   const removeFunctionSync = opts.unsafeCleanup ? FN_RIMRAF_SYNC : FN_RMDIR_SYNC;
320:   const removeCallbackSync = _prepareRemoveCallback(removeFunctionSync, name, sync);
321:   const removeCallback = _prepareRemoveCallback(removeFunction, name, sync, removeCallbackSync);
322:   if (!opts.keep) _removeObjects.unshift(removeCallbackSync);
323: 
324:   return sync ? removeCallbackSync : removeCallback;
325: }
326: 
327: /**
328:  * Creates a guarded function wrapping the removeFunction call.
329:  *
330:  * The cleanup callback is save to be called multiple times.
331:  * Subsequent invocations will be ignored.
332:  *
333:  * @param {Function} removeFunction
334:  * @param {string} fileOrDirName
335:  * @param {boolean} sync
336:  * @param {cleanupCallbackSync?} cleanupCallbackSync
337:  * @returns {cleanupCallback | cleanupCallbackSync}
338:  * @private
339:  */
340: function _prepareRemoveCallback(removeFunction, fileOrDirName, sync, cleanupCallbackSync) {
341:   let called = false;
342: 
343:   // if sync is true, the next parameter will be ignored
344:   return function _cleanupCallback(next) {
345:     /* istanbul ignore else */
346:     if (!called) {
347:       // remove cleanupCallback from cache
348:       const toRemove = cleanupCallbackSync || _cleanupCallback;
349:       const index = _removeObjects.indexOf(toRemove);
350:       /* istanbul ignore else */
351:       if (index >= 0) _removeObjects.splice(index, 1);
352: 
353:       called = true;
354:       if (sync || removeFunction === FN_RMDIR_SYNC || removeFunction === FN_RIMRAF_SYNC) {
355:         return removeFunction(fileOrDirName);
356:       } else {
357:         return removeFunction(fileOrDirName, next || function () {});
358:       }
359:     }
360:   };
361: }
362: 
363: /**
364:  * The garbage collector.
365:  *
366:  * @private
367:  */
368: function _garbageCollector() {
369:   /* istanbul ignore else */
370:   if (!_gracefulCleanup) return;
371: 
372:   // the function being called removes itself from _removeObjects,
373:   // loop until _removeObjects is empty
374:   while (_removeObjects.length) {
375:     try {
376:       _removeObjects[0]();
377:     } catch (e) {
378:       // already removed?
379:     }
380:   }
381: }
