383: /**
384:  * Random name generator based on crypto.
385:  * Adapted from http://blog.tompawlak.org/how-to-generate-random-values-nodejs-javascript
386:  *
387:  * @param {number} howMany
388:  * @returns {string} the generated random name
389:  * @private
390:  */
391: function _randomChars(howMany) {
392:   let value = [],
393:     rnd = null;
394: 
395:   // make sure that we do not fail because we ran out of entropy
396:   try {
397:     rnd = crypto.randomBytes(howMany);
398:   } catch (e) {
399:     rnd = crypto.pseudoRandomBytes(howMany);
400:   }
401: 
402:   for (let i = 0; i < howMany; i++) {
403:     value.push(RANDOM_CHARS[rnd[i] % RANDOM_CHARS.length]);
404:   }
405: 
406:   return value.join('');
407: }
408: 
409: /**
410:  * Checks whether the `obj` parameter is defined or not.
411:  *
412:  * @param {Object} obj
413:  * @returns {boolean} true if the object is undefined
414:  * @private
415:  */
416: function _isUndefined(obj) {
417:   return typeof obj === 'undefined';
418: }
419: 
420: /**
421:  * Parses the function arguments.
422:  *
423:  * This function helps to have optional arguments.
424:  *
425:  * @param {(Options|null|undefined|Function)} options
426:  * @param {?Function} callback
427:  * @returns {Array} parsed arguments
428:  * @private
429:  */
430: function _parseArguments(options, callback) {
431:   /* istanbul ignore else */
432:   if (typeof options === 'function') {
433:     return [{}, options];
434:   }
435: 
436:   /* istanbul ignore else */
437:   if (_isUndefined(options)) {
438:     return [{}, callback];
439:   }
440: 
441:   // copy options so we do not leak the changes we make internally
442:   const actualOptions = {};
443:   for (const key of Object.getOwnPropertyNames(options)) {
444:     actualOptions[key] = options[key];
445:   }
446: 
447:   return [actualOptions, callback];
448: }
