450: /**
451:  * Resolve the specified path name in respect to tmpDir.
452:  *
453:  * The specified name might include relative path components, e.g. ../
454:  * so we need to resolve in order to be sure that is is located inside tmpDir
455:  *
456:  * @private
457:  */
458: function _resolvePath(name, tmpDir, cb) {
459:   const pathToResolve = path.isAbsolute(name) ? name : path.join(tmpDir, name);
460: 
461:   fs.stat(pathToResolve, function (err) {
462:     if (err) {
463:       fs.realpath(path.dirname(pathToResolve), function (err, parentDir) {
464:         if (err) return cb(err);
465: 
466:         cb(null, path.join(parentDir, path.basename(pathToResolve)));
467:       });
468:     } else {
469:       fs.realpath(pathToResolve, cb);
470:     }
471:   });
472: }
473: 
474: /**
475:  * Resolve the specified path name in respect to tmpDir.
476:  *
477:  * The specified name might include relative path components, e.g. ../
478:  * so we need to resolve in order to be sure that is is located inside tmpDir
479:  *
480:  * @private
481:  */
482: function _resolvePathSync(name, tmpDir) {
483:   const pathToResolve = path.isAbsolute(name) ? name : path.join(tmpDir, name);
484: 
485:   try {
486:     fs.statSync(pathToResolve);
487:     return fs.realpathSync(pathToResolve);
488:   } catch (_err) {
489:     const parentDir = fs.realpathSync(path.dirname(pathToResolve));
490: 
491:     return path.join(parentDir, path.basename(pathToResolve));
492:   }
493: }
